import random  # Импортируем модуль random, чтобы генерировать случайные числа
list = [random.randint(0, 1000000) for i in range(100)]  # Создаем список из 100 случайных целых чисел от 0 до 1 000 000
a = list.copy()  # Делаем точную копию исходного списка для первого алгоритма (сортировки пузырьком)
b = 0  # Создаем переменную b, которая будет работать счетчиком сравнений для пузырька
n = len(a)  # Узнаем длину нашего списка (количество элементов в нем) и сохраняем в n
print("Сортировка пузырьком")  # Печатаем в консоль заголовок, чтобы отделить начало сортировки пузырьком
for i in range(n):  # Запускаем внешний цикл, который должен повториться n раз (по количеству элементов)
    for j in range(0, n - i - 1):  # Запускаем внутренний цикл, который идет по списку и сравнивает соседние числа
        b += 1  # При каждом шаге внутреннего цикла увеличиваем счетчик сравнений b на 1
        if a[j] < a[j + 1]:  # Если левое число меньше правого, значит они стоят не по убыванию
            a[j], a[j + 1] = a[j + 1], a[j]  # Меняем эти два соседних числа местами в списке
    print(f"Шаг {i + 1}: {a}")  # Выводим на экран, как выглядит список после каждого полного прохода пузырька
q = list.copy()  # Делаем еще одну чистую копию исходного списка для второго алгоритма (выбором)
f = 0  # Создаем переменную f, которая будет считать количество сравнений для выбора
print("Сортировка выбором")  # Печатаем в консоль заголовок для начала сортировки выбором
for i in range(n - 1):  # Запускаем внешний цикл от первого элемента списка до предпоследнего
    max_idx = i  # Временно считаем, что текущий элемент под индексом i и есть самый большой
    for j in range(i + 1, n):  # Запускаем внутренний цикл, чтобы искать максимум среди всех оставшихся чисел справа
        f += 1  # При каждом сравнении чисел увеличиваем счетчик сравнений f на 1
        if q[j] > q[max_idx]:  # Если нашли число, которое больше нашего текущего максимума
            max_idx = j  # Запоминаем индекс этого нового, более крупного числа
    q[i], q[max_idx] = q[max_idx], q[i]  # По окончании поиска меняем местами начальный элемент i и найденный максимум
    print(f"Шаг {i + 1}: {q}")  # Выводим на экран состояние списка после того, как очередной максимум встал на свое место
print(" результат")  # Выводим в консоль слово результат, чтобы обозначить финальный блок программы
print("Оригинальный список: ", list)  # Выводим на экран первоначальный список со случайным порядком чисел
print("Итоговый пузырьком:  ", a)  # Выводим итоговый отсортированный по убыванию список после пузырьковой сортировки
print("Итоговый выбором:     ", q)  # Выводим итоговый отсортированный по убыванию список после сортировки выбором
print("Сравнений в пузырьке:", b)  # Выводим общее число сравнений, которое накопилось в переменной b для пузырька
print("Сравнений в выборе:  ", f)  # Выводим общее число сравнений, которое накопилось в переменной f для выбора